    // Within each block of 4 rows:
    // Row 4*block+1: step 2*block+1, first attendant
    // Row 4*block+2: step 2*block+2, first attendant
    // Row 4*block+3: step 2*block+1, second attendant
    // Row 4*block+4: step 2*block+2, second attendant

