    // T(step) = sum_{i=1}^{step-1} (6 + move(i))
    //         = 6*(step-1) + sum_{i=1}^{step-1} move(i)

    // sum_{i=1}^{step-1} move(i):
    // move(i) = 1 if i odd, 3 if i even.
    // For i from 1 to step-1:
    // Number of odd i's: ceil((step-1)/2)
    // Number of even i's: floor((step-1)/2)

    long long numStepsBefore = step - 1;
    long long numOdd = (numStepsBefore + 1) / 2;
    long long numEven = numStepsBefore / 2;

    long long sumMove = numOdd * 1 + numEven * 3;
    long long timeBeforeStep = 6 * numStepsBefore + sumMove;

    // Now, within step `step`, how much time until Vasya's seat is served?
    // Both attendants work in parallel. The time within the step is determined by the attendant serving Vasya's row.
    // The attendant serves seats in order: f, e, d, c, b, a.
    // seatPos is 1 for f, 2 for e, ..., 6 for a.
    // So the time within the step is seatPos seconds.

    // But wait, is there any offset between the two attendants? No, they start at the same time and work at the same speed.
    // So the time Vasya gets his lunch is:
    // timeBeforeStep + seatPos

    long long totalTime = timeBeforeStep + seatPos;

    cout << totalTime << endl;

    return 0;
}
